ight:100px;font-size:42px}.body{white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0}.meta{font-size:12px;color:var(--muted)}.pill{display:inline-block;background:#f4e0ef;color:#883363;border-radius:99px;padding:4px 9px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.table{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;white-space:nowrap;padding:10px;border-bottom:1px solid var(--line)}.error,.notice{padding:12px;background:#fce2ee;border-radius:10px;margin:10px 0}.notice{background:#e7f4e9;color:#27603e}.footer{font-size:12px;color:var(--muted);margin-top:25px}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #c479aa;outline-offset:2px}@media(max-width:600px){.grid{grid-template-columns:1fr}header{padding:12px}nav{gap:9px}.card{padding:14px}}
