function form($a,$fields,$button,$multi=false){return '<form method="post"'.($multi?' enctype="multipart/form-data"':'').'>'.csrf().'<input type="hidden" name="action" value="'.h($a).'">'.$fields.'<button>'.h($button).'</button></form>';}
function input($name,$label,$value='',$type='text',$extra=''){return '<label>'.h($label).'</label><input name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.$extra.'>';}
function hidden($name,$value){return '<input type="hidden" name="'.h($name).'" value="'.h($value).'">';}
function area($name,$label,$value='',$max=2000){return '<label>'.h($label).'</label><textarea name="'.h($name).'" maxlength="'.(int)$max.'">'.h($value).'</textarea>';}
function check($name,$label,$checked=false){return '<label><input type="checkbox" name="'.h($name).'" value="yes"'.($checked?' checked':'').'> '.h($label).'</label>';}
function accountFields(){return input('username','Usuario (seudónimo)','','text','required maxlength="32" autocomplete="username" pattern="[a-zA-Z0-9_]{3,32}"').input('display_name','Nombre visible','','text','required maxlength="60"').input('password','Contraseña (mínimo 12 caracteres)','','password','required minlength="12" maxlength="72" autocomplete="new-password"');}
function q($sql,$args=[]){global $db;$s=$db->prepare($sql);$s->execute($args);return $s;}
function one($sql,$args=[]){return q($sql,$args)->fetch()?:null;}
function rows($sql,$args=[]){return q($sql,$args)->fetchAll();}
function flash($s){$_SESSION['flash']=$s;}
function needUser(){global $me;if(!$me)err('Iniciá sesión primero.');}
function needAdmin(){global $me;needUser();if($me['role']!=='admin')err('No autorizado.');}
function username($x){$x=strtolower(trim($x));if(!preg_match('/^[a-z0-9_]{3,32}$/D',$x))err('Usuario: 3 a 32 letras, números o guiones bajos.');return $x;}
function passwordHash($s){if(strlen($s)<12||strlen($s)>72)err('Contraseña: entre 12 y 72 bytes.');return password_hash($s,PASSWORD_DEFAULT);}
function addUser($role='member'){$n=username(p('username'));$d=clean(p('display_name'),60,true);$hash=passwordHash(p('password'));if(one('SELECT id FROM studio_users WHERE username=?',[$n]))err('Usuario no disponible.');q('INSERT INTO studio_users(username,display_name,password_hash,role) VALUES(?,?,?,?)',[$n,$d,$hash,$role]);return one('SELECT id FROM studio_users WHERE username=?',[$n]);}
function logIn($u){session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));}
function rate($name,$max,$seconds){global $cfg;$b=hash_hmac('sha256',$name,$cfg['setup_key']);$slot=(int)floor(time()/$seconds);q('INSERT INTO studio_limits(bucket,slot,hits) VALUES(?,?,1) ON DUPLICATE KEY UPDATE hits=IF(slot=VALUES(slot),hits+1,1),slot=VALUES(slot)',[$b,$slot]);if((int)one('SELECT hits FROM studio_limits WHERE bucket=?',[$b])['hits']>$max)err('Demasiados intentos. Probá más tarde.');}
function ip(){return $_SERVER['REMOTE_ADDR']??'unknown';}
function avatarUpload(){if(!isset($_FILES['avatar'])||$_FILES['avatar']['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES['avatar'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152||!is_uploaded_file($f['tmp_name']))err('Imagen de hasta 2 MB.');if(!function_exists('imagecreatefromstring'))err('El hosting debe habilitar GD.');$i=@getimagesize($f['tmp_name']);if(!$i||!in_array($i['mime'],['image/jpeg','image/png','image/webp'],true)||min($i[0],$i[1])<1||max($i[0],$i[1])>2048)err('Elegí JPG, PNG o WebP de hasta 2048 × 2048.');$im=@imagecreatefromstring((string)file_get_contents($f['tmp_name']));if(!$im)err('Imagen inválida.');$dst=imagecreatetruecolor(256,256);imagefill($dst,0,0,imagecolorallocate($dst,255,240,248));$side=min($i[0],$i[1]);imagecopyresampled($dst,$im,0,0,(int)(($i[0]-$side)/2),(int)(($i[1]-$side)/2),256,256,$side,$side);ob_start();imagejpeg($dst,null,85);$data=ob_get_clean();imagedestroy($im);imagedestroy($dst);if(!$data)err('No se pudo procesar la imagen.');return $data;}
