if($v==='profile'){$u=one('SELECT id,display_name,style,bio,visible,avatar IS NOT NULL AS has_avatar FROM studio_users WHERE id=? AND active=1',[$id?:$me['id']]);$own=$u&&$u['id']==$me['id'];if(!$u||(!$own&&!$u['visible'])){http_response_code(404);page('Perfil',card('Ficha privada o no disponible.'));}
$body.='<div class="hero row">'.avatar($u,true).'<div><div class="eyebrow">Ficha personal</div><h1>'.h($u['display_name']).'</h1><span class="pill">'.h($u['style']?:'Explorando mi estilo').'</span>'.($own?' <span class="pill">'.($u['visible']?'Visible a miembros':'Privada').'</span>':'').'</div></div>'.card('<h2>Sobre mí</h2><div class="body">'.h($u['bio']?:'Todavía no hay descripción.').'</div>');
if($own){$body.=card('<h2>Editar mi ficha</h2>'.form('profile',input('display_name','Nombre visible',$u['display_name'],'text','required maxlength="60"').input('style','Mi estilo',$u['style'],'text','maxlength="100"').area('bio','Sobre mí',$u['bio'],600).input('avatar','Avatar JPG, PNG o WebP hasta 2 MB','','file','accept="image/jpeg,image/png,image/webp"').check('remove_avatar','Quitar avatar').check('visible','Compartir mi ficha y avatar con miembros registrados',(bool)$u['visible']),'Guardar',true)).card('<h2>Cambiar contraseña</h2>'.form('password',input('current','Contraseña actual','','password','required autocomplete="current-password"').input('password','Nueva contraseña','','password','required minlength="12" maxlength="72" autocomplete="new-password"'),'Actualizar'));}page('Perfil',$body);}
if($v==='admin'){$body.=hero('Administración de usuarios','Altas, edición, suspensión, bajas y moderación. Registro: '.($open?'abierto':'cerrado').'.').card('<h2>Alta manual</h2>'.form('admin_create',accountFields(),'Crear usuario'));$t='<h2>Listado</h2><div class="table"><table><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';foreach(rows('SELECT id,username,display_name,role,active FROM studio_users ORDER BY id DESC LIMIT 200')as $u)$t.='<tr><td>'.h($u['username']).'</td><td>'.h($u['display_name']).'</td><td>'.h($u['role']).'</td><td>'.($u['active']?'Activo':'Suspendido').'</td><td>'.($u['role']==='member'?'<a href="'.h(linkTo('edituser',$u['id'])).'">Editar / baja</a>':'').'</td></tr>';page('Administración',$body.card($t.'</tbody></table></div>'));}
if($v==='edituser'){$u=one("SELECT id,username,display_name,active FROM studio_users WHERE id=? AND role='member'",[$id]);if(!$u)page('Editar',card('Usuario no disponible.'));$body.=card('<h2>Editar usuario</h2>'.form('admin_update',hidden('id',$id).input('username','Usuario',$u['username'],'text','required maxlength="32"').input('display_name','Nombre visible',$u['display_name'],'text','required maxlength="60"').input('password','Nueva contraseña (opcional)','','password','minlength="12" maxlength="72" autocomplete="new-password"').check('active','Cuenta activa',(bool)$u['active']),'Guardar')).card('<h2>Baja definitiva</h2><p>Elimina la cuenta, avatar y mensajes, incluidas las respuestas de sus temas.</p>'.form('admin_delete',hidden('id',$id).check('confirm','Confirmo la eliminación irreversible.'),'Eliminar cuenta'));page('Editar',$body);}
page('Comunidad',card('Sección no disponible.'));
